SELECT toString(week) AS week_start, countIf(visited) AS visitors, countIf(opened) AS form_openers, countIf(lead OR (cv AND last_body_apply > first_cv)) AS tracked_submissions FROM (SELECT person_id, toStartOfWeek(toTimeZone(timestamp, 'Asia/Dubai'), 1) AS week, countIf(event = '$pageview') > 0 AS visited, countIf(event = 'click_open_form') > 0 AS opened, countIf(event = 'lead_join_our_team') > 0 AS lead, countIf(event = 'cta_click' AND properties.cta_name = 'choose_file') > 0 AS cv, minIf(timestamp, event = 'cta_click' AND properties.cta_name = 'choose_file') AS first_cv, maxIf(timestamp, event = 'cta_click' AND properties.cta_name = 'apply_now' AND properties.cta_location = 'join_our_team_body') AS last_body_apply FROM events WHERE timestamp >= toDateTime('2026-09-21 00:00:00', 'Asia/Dubai') AND timestamp < now() AND properties.$pathname LIKE '/en/join-our-team%' AND event IN ('$pageview', 'click_open_form', 'lead_join_our_team', 'cta_click') AND coalesce(properties.$virt_is_bot, false) = false GROUP BY person_id, week) GROUP BY week_start ORDER BY week_start LIMIT 200
